"/**
 * DUNGEON MAP DATA
 * Represents the 2D layout of each floor.
 * 
 * Legend:
 * . : Empty space (walkable)
 * # : Wall (impassable)
 * E : Enemy encounter (Slime)
 * S : Starting position
 */

const floors = {
    1: {
        map: [
            "#######",
            "#.....#",
            "#.###.#",
            "#.E.#.#",
            "###.#.#",
            "#...#.#",
            "#S###.#",
            "#######"
        ],
        startPos: { x: 1, y: 6 },
        width: 7,
        height: 8
    }
};

let currentMap = [];
let playerPos = { x: 1, y: 6 };

function loadMap(floorNum) {
    const floorData = floors[floorNum];
    currentMap = floorData.map.map(row => row.split(''));
    playerPos = { ...floorData.startPos };
}

function getTile(x, y) {
    if (y < 0 || y >= currentMap.length || x < 0 || x >= currentMap[y].length) return '#';
    return currentMap[y][x];
}"

