"const fs = require('fs');
const path = require('path');
const vm = require('vm');

const files = ['enemies.js', 'map.js', 'story.js', 'game.js'];
const dir = __dirname;

// Mock DOM environment for game.js
const mockDom = {
    document: {
        getElementById: () => ({ classList: { add: () => {}, remove: () => {} }, style: {}, innerHTML: '', appendChild: () => {} }),
        querySelector: () => ({ innerText: '' }),
        createElement: () => ({ style: {}, classList: { add: () => {} } })
    },
    window: {},
    console: console
};

const context = vm.createContext(mockDom);

for (const file of files) {
    const filePath = path.join(dir, file);
    try {
        console.log(`Checking ${file}...`);
        const code = fs.readFileSync(filePath, 'utf8');
        vm.runInContext(code, context, { filename: file });
        console.log(`${file} is syntax-valid!`);
    } catch (err) {
        console.error(`ERROR in ${file}:`, err.message);
        process.exit(1);
    }
}
console.log("All files checked successfully!");
"

